<template><view class="ld-page has-tabbar prototype-workspace"><view class="ld-topbar"><view class="profile-avatar">{{name.slice(0,1)||'灵'}}</view><view class="profile-copy"><text class="ld-topbar-name">{{name||'成长伙伴'}}</text><text class="ld-topbar-meta">{{username}}</text></view></view><view class="ld-heading"><text class="ld-heading-title">我的</text><text class="ld-heading-sub">账号与成长空间</text></view><view v-if="error" class="ld-card">{{error}}</view><view class="ld-group"><button v-if="permissions.includes('ORGANIZATION_ONBOARDING_READ')" class="ld-cell" @tap="myOrganizations"><view class="ld-cell-icon"><PrototypeIcon name="school" :size="24"/></view><view class="ld-cell-body"><text class="ld-cell-title">我的组织</text><text class="ld-cell-sub">组织成员、学员与日常管理</text></view><text class="ld-cell-arrow">›</text></button><button class="ld-cell" @tap="switchOrganization"><view class="ld-cell-icon"><PrototypeIcon name="school" :size="24"/></view><view class="ld-cell-body"><text class="ld-cell-title">切换组织</text><text class="ld-cell-sub">选择家庭或学校、培训机构</text></view><text class="ld-cell-arrow">›</text></button><button class="ld-cell" @tap="settings"><view class="ld-cell-icon"><PrototypeIcon name="lock" :size="24" /></view><view class="ld-cell-body"><text class="ld-cell-title">账号设置</text><text class="ld-cell-sub">联系方式、密码与组织选择</text></view><text class="ld-cell-arrow">›</text></button><button v-if="securityEnabled" class="ld-cell" @tap="security"><view class="ld-cell-icon"><PrototypeIcon name="shield" :size="24" /></view><view class="ld-cell-body"><text class="ld-cell-title">账号安全</text><text class="ld-cell-sub">登录设备与安全事件</text></view><text class="ld-cell-arrow">›</text></button></view><view class="ld-group"><button v-if="permissions.includes('ORG_MEMBER_READ')" class="ld-cell" @tap="openMembers"><view class="ld-cell-icon"><PrototypeIcon name="people" :size="24"/></view><view class="ld-cell-body"><text class="ld-cell-title">组织成员</text><text class="ld-cell-sub">成员与管理员设置</text></view><text class="ld-cell-arrow">›</text></button></view><OrganizationOwnerTransfer identity="organization"/><button class="logout-button" :disabled="leaving" @tap="logout">退出登录</button><AppTabBar :items="teacher?TEACHER_TABS:ORG_TABS" :active="3"/></view></template>
<script setup lang="ts">
function switchOrganization(){uni.navigateTo({url:"/pages/my-organizations/my-organizations?identity=organization&choose=1"});}

import PrototypeIcon from '@/components/PrototypeIcon.vue';import {ref} from 'vue';import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app';import AppTabBar from '@/components/AppTabBar.vue';import OrganizationOwnerTransfer from '@/components/OrganizationOwnerTransfer.vue';import {TEACHER_TABS,ORG_TABS} from '@/config/tabbar';import {request} from '@/api/http';import {getMiniappCapabilities} from '@/api/capability';import {getOrganizationSession,clearOrganizationSession} from '@/session/organization-session';import {logoutOrganization} from '@/api/auth';const permissions=ref<string[]>([]);function openMembers(){uni.navigateTo({url:"/pages/organization-members/organization-members"});}const teacher=ref(false),name=ref(''),username=ref(''),error=ref(''),securityEnabled=ref(false),leaving=ref(false);let revision=0;onLoad(q=>{teacher.value=q?.identity==='teacher';});onHide(()=>{revision++;});onUnload(()=>{revision++;});onShow(async()=>{const n=++revision,session=getOrganizationSession();name.value='';username.value='';error.value='';securityEnabled.value=false;permissions.value=[];if(!session){await uni.reLaunch({url:'/pages/unified-login/unified-login'});return;}try{const [me,c]=await Promise.all([request<{displayName:string;username:string;permissionCodes:string[]}>('/auth/me',{header:{Authorization:`Bearer ${session.accessToken}`}}),getMiniappCapabilities()]);if(n!==revision||getOrganizationSession()?.accessToken!==session.accessToken)return;permissions.value=me.permissionCodes;name.value=me.displayName;username.value=me.username;securityEnabled.value=c.accountSecurityManagementEnabled;}catch(e){if(n===revision)error.value=e instanceof Error?e.message:'账号信息加载失败';}});function myOrganizations(){if(permissions.value.includes('ORGANIZATION_ONBOARDING_READ'))uni.navigateTo({url:'/pages/organization-overview/organization-overview?identity=organization'});}function settings(){uni.navigateTo({url:'/pages/account-settings/account-settings?identity=organization'});}function security(){uni.navigateTo({url:'/pages/account-security/account-security?identity=organization'+(teacher.value?'&workbench=teacher':'')});}async function logout(){const s=getOrganizationSession();if(!s||leaving.value)return;leaving.value=true;try{await logoutOrganization(s.accessToken);}catch{/* Local logout still completes when the server is unavailable. */}finally{if(getOrganizationSession()?.accessToken===s.accessToken){clearOrganizationSession();await uni.reLaunch({url:'/pages/unified-login/unified-login'});}leaving.value=false;}}</script>
